{"command": "cd /app && python3 - <<'EOF'
s = open('scan_persistence.sh').read()

old = '''    case "$tok" in
        /usr/bin/*|/bin/*|/sbin/*|/usr/sbin/*|/usr/lib/*|/lib/*) return 0 ;;
        /etc/cron.hourly|/etc/cron.daily|/etc/cron.weekly|/etc/cron.monthly) return 0 ;;
        /etc/update-motd.d/*|/etc/rc.local|/run/systemd/system|/sysroot) return 0 ;;
    esac'''
new = '''    case "$tok" in
        /usr/bin/*|/bin/*|/sbin/*|/usr/sbin/*|/usr/lib/*|/lib/*) return 0 ;;
        /etc/cron.hourly|/etc/cron.daily|/etc/cron.weekly|/etc/cron.monthly) return 0 ;;
        /etc/update-motd.d/*|/etc/rc.local|/etc/fstab|/sysroot) return 0 ;;
        /proc/*|/sys/*|/run/*|/system-update) return 0 ;;
    esac'''
assert old in s
s = s.replace(old, new)

old = "grep -qE '^(\\*|[0-9/,+-]+)([[:space:]]+(\\*|[0-9/,+-]+)){4}$'"
new = "grep -qE '^(\\*|[0-9*/,+-]+)([[:space:]]+(\\*|[0-9*/,+-]+)){4}$'"
assert old in s
s = s.replace(old, new)

open('scan_persistence.sh','w').write(s)
print("patched")
EOF
bash -n /app/scan_persistence.sh && /app/scan_persistence.sh; echo "exit=$?"
jq -r '.summary' /app/persistence_report.json
jq -r '.artifacts[] | "\(.type)\t\(.path)\t\(.details.line_number)\t\(.details.user)"' /app/persistence_report.json"}

